const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');const stages=['Name it','Set boundaries','Find options','Question it','Weigh it up','Move forward'];let data={},step=0,records=[];try{records=JSON.parse(localStorage.getItem('clearing-records')||'[]');if(!Array.isArray(records))records=[]}catch{}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const get=k=>esc(data[k]||'');const count=()=>document.querySelector('#count').textContent=records.length;count();function toast(t){const el=document.createElement('div');el.className='toast';el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),2800)}function persist(){try{localStorage.setItem('clearing-records',JSON.stringify(records));count();return true}catch{toast('Storage unavailable. Keep this tab open or print your reflection.');return false}}function save(){capture();data.step=step;data.updated=new Date().toISOString();const i=records.findIndex(r=>r.id===data.id);if(i<0)records.unshift(structuredClone(data));else records[i]=structuredClone(data);return persist()}function home(){app.innerHTML=`<section class="home"><div class="hero"><div><div class="eyebrow">A space to think things through</div><h1>A tangled mind.<br>A <em>clearer</em> way.</h1><p class="intro">Big decisions. Everyday dilemmas.<br>Find your way through, one good question at a time.</p><div class="startrow"><button class="primary" id="begin">Untangle a decision</button><span class="small">Your pace. Your answers.<br>About 5–10 minutes.</span></div></div><div class="art" aria-hidden="true"><span class="art-label top">IT STARTS A LITTLE TANGLED.</span><svg viewBox="0 0 470 370" fill="none"><ellipse cx="250" cy="210" rx="145" ry="115" fill="#e9e3f2" opacity=".35"/><path d="M28 164C88 60 301 29 322 130S78 341 100 176 370 78 329 236 114 307 144 130 362 53 355 219 108 293 176 112 398 186 293 268 181 63 288 99 251 298 210 215 333 128 323 233 393 277 433 208" stroke="#8c79a9" stroke-width="1.4"/><path d="M30 174C81 61 293 30 313 128S82 333 109 179 358 87 321 231 126 303 153 136 350 62 346 217 120 283 182 120 383 186 289 260 188 75 282 106 252 281 216 212 328 141 331 229 392 267 433 208" stroke="#b9aaca" stroke-width=".7"/><circle cx="433" cy="208" r="5" fill="#7161aa"/><path d="M433 208C450 186 458 170 459 155" stroke="#7161aa" stroke-width="1.3"/></svg><span class="art-chip">Let’s find the thread.</span><span class="art-label bottom">IT DOESN’T HAVE TO STAY THAT WAY.</span></div></div><section class="examples"><div class="section-label"><strong>Not sure where to start?</strong><span>Borrow a question. Make it yours.</span></div><div class="cards"><button class="example" data-example="career"><span class="tag"><span class="symbol">⌘</span> WORK & DIRECTION</span><h3>Should I stay, or take<br>the new opportunity?</h3></button><button class="example" data-example="time"><span class="tag"><span class="symbol">◷</span> TIME & ENERGY</span><h3>Too much to do.<br>What actually matters?</h3></button><button class="example" data-example="money"><span class="tag"><span class="symbol">◇</span> MONEY & PRIORITIES</span><h3>Do I need this,<br>or do I just want it?</h3></button></div><div class="bottom-note"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor"><rect x="4" y="8" width="12" height="10" rx="2"/><path d="M6 8V5a4 4 0 0 1 8 0v3"/></svg>Your reflections stay in this browser. No account for your thoughts.</div></section></section>`;document.querySelector('#begin').onclick=()=>start();document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>start(b.dataset.example))}function start(example){data={id:Date.now().toString(),category:example==='money'?'Money':example==='career'?'Work':example==='time'?'Time':'Life',limits:[],ratings:{},question:{career:'Should I stay in my current role or take a new opportunity?',time:'How should I spend my limited time this week?',money:'Should I buy this now or save the money?'}[example]||''};step=0;render()}
function field(k,label,placeholder='',type='textarea'){return `<label class="field"><span>${label}</span>${type==='textarea'?`<textarea name="${k}" placeholder="${placeholder}">${get(k)}</textarea>`:`<input type="${type}" name="${k}" value="${get(k)}" placeholder="${placeholder}">`}</label>`}function capture(){app.querySelectorAll('[name]').forEach(el=>{if(el.type==='checkbox')data[el.name]=el.checked;else data[el.name]=el.value});app.querySelectorAll('[data-rating]').forEach(el=>{data.ratings[el.dataset.rating]=Number(el.value)})}function options(){return [data.a,data.b,data.c].filter(s=>s&&s.trim())}function render(){app.innerHTML=`<section class="workspace"><div class="workspace-head"><button class="textbtn" id="exit">Close reflection</button><span class="small">A little clarity, one question at a time.</span><button class="textbtn" id="save">Save & pause</button></div><div class="flow"><aside class="steps" aria-label="Reflection progress">${stages.map((s,i)=>`<button class="step ${step===i?'active':i<step?'done':''}" data-step="${i}" ${i>step?'disabled':''}><i></i>${s}</button>`).join('')}</aside><div class="sheet"><div class="eyebrow">${step===6?'Your clearing':stages[step]}</div>${content()}<div id="error" class="error" role="alert"></div>${step<6?`<div class="actions"><button class="textbtn" id="back">${step?'Back':'Take your time. There’s no perfect answer.'}</button><button class="primary" id="next">${step===5?'See my reflection':'Continue'}</button></div>`:''}</div></div></section>`;document.querySelector('#exit').onclick=()=>{save();home()};document.querySelector('#save').onclick=()=>{if(save()){home();toast('Your reflection is saved in this browser.')}};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{capture();step=Number(b.dataset.step);render()});document.querySelectorAll('[data-limit]').forEach(b=>b.onclick=()=>{capture();const l=b.dataset.limit;data.limits=data.limits.includes(l)?data.limits.filter(x=>x!==l):[...data.limits,l];render()});const next=document.querySelector('#next');if(next)next.onclick=()=>{capture();let err=validate();if(err){document.querySelector('#error').textContent=err;return}step++;save();render();window.scrollTo({top:0,behavior:'smooth'})};const back=document.querySelector('#back');if(back)back.onclick=()=>{if(step){capture();step--;render()}};document.querySelectorAll('[data-rating]').forEach(el=>el.oninput=()=>el.nextElementSibling.textContent=el.value);if(step===6){document.querySelector('#print').onclick=()=>window.print();document.querySelector('#edit').onclick=()=>{step=0;render()};document.querySelector('#new').onclick=()=>{save();start()}}}
function content(){switch(step){case 0:return `<h2>What’s on your mind?</h2><p class="subtitle">Give the decision a name. Something specific enough to work with, small enough to hold.</p>${field('question','The decision I’m facing','Should I…? How can I…? What should I prioritize?')}${field('goal','What would a good outcome look like?','Describe what you want to be different.')}<label class="field"><span>Which part of life does this touch?</span><select name="category">${['Life','Work','Time','Money','Relationships','Learning'].map(x=>`<option ${data.category===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="insight"><strong>A useful reframe</strong><br>“My life is stressful” is a feeling. “Which commitment can I reduce this week?” is a decision you can work with.</div>`;case 1:return `<h2>What are you working with?</h2><p class="subtitle">Good choices fit real life. Name your limits, then separate the fixed ones from the negotiable ones.</p><div class="chips">${['Time','Money','Energy','Responsibilities','Other people'].map(l=>`<button class="chip ${data.limits.includes(l)?'selected':''}" data-limit="${l}" aria-pressed="${data.limits.includes(l)}">${l}</button>`).join('')}</div>${field('hard','What absolutely cannot be compromised?',data.limits.includes('Money')?'For example: I cannot spend more than ₹5,000.':'For example: I have two hours a week and need to protect my sleep.')}${field('soft','What could bend, even a little?','A preference, a timeline, or a way you normally do things.')}<div class="two">${field('deadline','When do you need to decide?','','date')}${field('priority','What matters most to you?','For example: stability, growth, time','text')}</div><div class="insight"><strong>Check the boundary</strong><br>${data.limits.includes('Other people')?'Whose agreement do you actually need? Separate their stated needs from what you assume they expect.':data.limits.includes('Energy')?'A plan that fits your calendar may still exceed your energy. What could you sustain on an ordinary, difficult day?':'Is this a real limit, or a rule you have never questioned? A hard constraint needs a specific boundary.'}</div>`;case 2:return `<h2>There’s usually a third way.</h2><p class="subtitle">Write at least two genuinely different options. Include doing nothing, delaying, or trying a smaller version if those are realistic.</p>${field('a','One way forward','Describe your first option.','text')}${field('b','Another way forward','What else could you do?','text')}${field('c','A third possibility · optional','A smaller test, a compromise, or keeping things as they are.','text')}<div class="insight"><strong>Your boundary stays in view</strong><br>${get('hard')}<br>Which options can realistically work inside this?</div>`;case 3:return `<h2>Let’s question the story.</h2><p class="subtitle">You don’t need certainty. You do need to notice the difference between what you know and what you’re predicting.</p>${field('facts','What do you know, and how do you know it?','List facts you could verify. Where did the information come from?')}${field('assumption','What are you assuming will happen?','Name a prediction you might be treating as a fact.')}${field('counter','What evidence would change your mind?','What could show your preferred option is wrong?')}<div class="insight"><strong>A different lens · ${get('category')}</strong><br>${({Money:'If nobody else could see this purchase, would you still want it? What would this money no longer be available for?',Work:'Are you comparing a real current situation with an idealized new one? What should you verify with someone who knows the new role?',Time:'If you could only finish one thing, which would make the rest easier or less necessary?',Relationships:'What has the other person actually said, and what are you inferring? What respectful question could clarify the difference?',Learning:'Are you choosing what looks impressive or what moves you toward your goal? What small trial would give you useful evidence?',Life:'What would you tell a friend in exactly this situation? What might they notice that you are missing?'})[data.category]}</div>`;case 4:return `<h2>Make the trade-offs visible.</h2><p class="subtitle">Score each option from 1 (low) to 5 (high). These are your judgments, not predictions. Your top priority: <strong>${get('priority')||'your desired outcome'}</strong>.</p>${options().map((o,i)=>`<div class="option-card"><h3>${esc(o)}</h3>${[['fit','Fit with your goal'],['feasible','Practical with your limits'],['values','Fit with what matters most']].map(([k,label])=>`<label class="range-line"><span>${label}</span><span style="display:flex;gap:12px;align-items:center"><input aria-label="${esc(o)}: ${label}" type="range" min="1" max="5" value="${data.ratings[i+'-'+k]||3}" data-rating="${i}-${k}"><output>${data.ratings[i+'-'+k]||3}</output></span></label>`).join('')}<label class="check"><input name="blocked${i}" type="checkbox" ${data['blocked'+i]?'checked':''}>This option breaks a non-negotiable limit</label></div>`).join('')}${field('tradeoff','What would you give up, even with your best option?','Time, comfort, money, another opportunity…')}<div class="insight"><strong>A score is a prompt, not a verdict.</strong><br>Hard limits override totals. A high score cannot make an impossible option practical.</div>`;case 5:return `<h2>Clarity becomes a small step.</h2><p class="subtitle">You can make a thoughtful choice while still feeling uncertain. Choose a direction and a way to learn.</p><label class="field"><span>Which direction will you take for now?</span><select name="choice"><option value="">Choose a direction</option>${options().map((o,i)=>`<option value="${esc(o)}" ${data.choice===o?'selected':''} ${data['blocked'+i]?'disabled':''}>${esc(o)}${data['blocked'+i]?' — outside your limits':''}</option>`).join('')}<option value="Gather more information" ${data.choice==='Gather more information'?'selected':''}>Gather more information</option></select></label>${field('why','Why is this the right next direction for you?','Connect your choice to the facts, your limits, and what matters.')}${field('action','What is one small action you can take?','Be specific: what will you do, and when?')}${field('review','When will you review what you learned?','','date')}<div class="insight"><strong>Keep the decision revisable</strong><br>What is the smallest reversible test? If you need more information, make gathering it your next action.</div>`;default:return summary()}}
function validate(){const required={0:['question','goal'],1:['hard','priority'],2:['a','b'],3:['facts','assumption','counter'],4:['tradeoff'],5:['choice','why','action']}[step]||[];if(required.some(k=>!String(data[k]||'').trim()))return 'Give each main question a short answer before continuing. Optional fields can stay blank.';if(step===2&&new Set(options().map(x=>x.trim().toLowerCase())).size!==options().length)return 'Try two different options so you have a real comparison.';return ''}function summary(){const scores=options().map((o,i)=>({o,blocked:data['blocked'+i],score:['fit','feasible','values'].reduce((s,k)=>s+(data.ratings[i+'-'+k]||3),0)})).sort((a,b)=>b.score-a.score);return `<h2>A little less tangled.</h2><p class="subtitle">Your thinking, brought together. You made the judgments. This is a record of your reasoning, not a guarantee of the outcome.</p><h3 class="summary-title">${get('question')}</h3><div class="insight"><strong>Your direction</strong><br>${get('choice')}<br><br>${get('why')}</div><div class="summary-grid">${[['goal','The outcome you want'],['hard','Your non-negotiables'],['facts','What you know'],['assumption','What remains an assumption'],['counter','What could change your mind'],['tradeoff','The trade-off you accept'],['action','Your next small step'],['review','Your review date']].map(([k,l])=>`<div class="summary-block"><label>${l}</label><p>${get(k)||'Not set'}</p></div>`).join('')}</div><div class="summary-block"><label>Your option comparison</label>${scores.map(s=>`<div class="ranking"><span style="flex:1">${esc(s.o)}${s.blocked?' · Outside your limits':''}</span><span class="bar"><div style="width:${s.score/15*100}%"></div></span><span>${s.score}/15</span></div>`).join('')}<p class="small">Equal weight across goal fit, practicality, and priorities. Scores reflect your inputs; excluded options remain visible for transparency.</p></div><div class="actions"><button class="textbtn" id="edit">Revisit my answers</button><button class="primary" id="print">Print / save as PDF</button></div><button id="new" class="textbtn" style="margin-top:25px">Start another reflection</button>`}
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(data.id)save();home()};document.querySelector('#method').onclick=()=>{document.querySelector('#dialogContent').innerHTML='<div class="eyebrow">The approach</div><h2>Better questions.<br>Your own answers.</h2><p>Clearing is a structured reflection tool. It guides your thinking with questions and simple comparisons; it does not generate AI advice or decide for you.</p><p><strong>Name it.</strong> Turn a feeling into a specific decision.<br><strong>Set boundaries.</strong> Separate hard limits from preferences.<br><strong>Find options.</strong> Look beyond the obvious either/or.<br><strong>Question it.</strong> Check facts, assumptions, and blind spots.<br><strong>Weigh it up.</strong> Make the trade-offs visible.<br><strong>Move forward.</strong> Take a small step and review.</p><p>Your reflections are saved only in this browser. They are not synced across devices and may be lost if browser data is cleared. On a shared device, delete reflections when finished.</p>';dialog.showModal()};document.querySelector('#saved').onclick=showSaved;function showSaved(){document.querySelector('#dialogContent').innerHTML=`<div class="eyebrow">Your space</div><h2>Threads to return to.</h2><p>Saved in this browser. Pick up where you left off.</p>${records.length?records.map(r=>`<div class="saved-item"><button data-resume="${esc(r.id)}">${esc(r.question||'Untitled reflection')}<small>${r.step===6?'Completed':stages[r.step||0]} · ${new Date(r.updated).toLocaleDateString()}</small></button><button class="textbtn" data-delete="${esc(r.id)}">Delete</button></div>`).join(''):'<p>No saved reflections yet. A good question is a good beginning.</p>'}`;document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>{data=structuredClone(records.find(r=>r.id===b.dataset.resume));step=data.step||0;dialog.close();render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{records=records.filter(r=>r.id!==b.dataset.delete);persist();showSaved()});if(!dialog.open)dialog.showModal()}document.querySelector('.close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};home();
